pub const TABLE: Table = Table { items: &ITEMS, operands: &OPERANDS };

/// The pattern predicates still checked when a function is selected.
pub fn pattern_predicate<C: PatternContext>(ctx: &C, id: u16) -> bool {
    match id {
        _ => unreachable!("pattern predicate {id} is not in this table"),
    }
}

/// The node predicates the table checks.
pub fn node_predicate<D: Dag, H: Hooks<D>>(dag: &D, hooks: &H, value: SDValue, id: u16) -> bool {
    let args = (dag, hooks, value);
    match id {
        0 => predicates::memory_vt_i8(args),
        1 => predicates::unindexed_store(args),
        2 => predicates::non_truncating_store(args),
        3 => predicates::non_extending_load(args),
        4 => predicates::zext_load(args),
        5 => predicates::ext_load(args),
        6 => predicates::unindexed_load(args),
        _ => unreachable!("node predicate {id} is not in this table"),
    }
}

